def convert_llm_inputs(
    prompts: List[str],
) -> Dict[str, str]:
    """
    Convert LLM inputs format from
    ["prompt1"...]
    to
    {"prompt": "prompt1"}
    """
    if len(prompts) == 0:
        prompt = ""
    elif len(prompts) == 1:
        prompt = prompts[0]
    else:
        raise NotImplementedError(f"Multiple prompts not supported yet. Got: {prompts}")
    return {"prompt": prompt}


